// This function receives a COPY of the number
void tryToChange(int x) {
  x = x + 100;
  printf("Inside function: %d\n", x);
}
int main() {
  int myNumber = 10;
  tryToChange(myNumber);
  // The original remains 10 because only the copy was changed
  printf("Outside function: %d\n", myNumber);
